export type Card = { monster: string; rank?: number };

const SPHINX = "sphinx";
const POINTS_WITHIN_THREE_TYPES = 2;
const THREE_TYPES = 3;
const FIRST_TYPE_BEYOND_THREE = 4;
const POINTS_FOR_FIRST_TYPE_BEYOND_THREE = 1;
const POINTS_PER_FURTHER_TYPE = 2;

const countDistinctMonsterTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const countSphinxes = (army: Card[]): number =>
  army.filter((card) => card.monster === SPHINX).length;

const pointsBeyondThreeTypes = (distinctTypes: number): number =>
  POINTS_FOR_FIRST_TYPE_BEYOND_THREE +
  POINTS_PER_FURTHER_TYPE * (distinctTypes - FIRST_TYPE_BEYOND_THREE);

const pointsPerSphinx = (distinctTypes: number): number =>
  distinctTypes > THREE_TYPES
    ? pointsBeyondThreeTypes(distinctTypes)
    : POINTS_WITHIN_THREE_TYPES;

export const scoreArmy = (army: Card[]): number =>
  countSphinxes(army) * pointsPerSphinx(countDistinctMonsterTypes(army));
